import { expect, expectStatus, test } from "../../fixtures";

test("A vendor from another tenant is not found", { tag: "@VEN-07" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor that belongs to another company, and a confirmed read of it there
  const otherTenant = await factory.vendor({ as: "otherTenant" });
  const otherTenantApi = await apiAs("otherTenant");
  expectStatus(await otherTenantApi.get(`/api/vendors/${otherTenant.id}`), 200);

  // Act: a Northwind member requests that vendor by id
  const member = await apiAs("member");
  const response = await member.get(`/api/vendors/${otherTenant.id}`);

  // Assert
  const body = await expectStatus(response, 404);
  expect(body.error.code).toBe("vendor_not_found");
});
